import { useId } from 'react';
import type { SVGAttributes } from 'react';

/**
 * The viSparkle mark: a white sparkle on a violet→pink rounded square. Colours are fixed, so it reads the same
 * on light and dark backgrounds (same artwork as public/favicon.svg, generated by resources/brand/generate.php).
 */
export default function AppLogoIcon(props: SVGAttributes<SVGElement>) {
    const gradient = useId();

    return (
        <svg
            {...props}
            viewBox="0 0 100 100"
            xmlns="http://www.w3.org/2000/svg"
        >
            <defs>
                <linearGradient id={gradient} x1="0" y1="0" x2="1" y2="1">
                    <stop offset="0" stopColor="#7c3aed" />
                    <stop offset="1" stopColor="#ec4899" />
                </linearGradient>
            </defs>
            <rect width="100" height="100" rx="22" fill={`url(#${gradient})`} />
            <path
                fill="#fff"
                d="M50 14 Q55 45 86 50 Q55 55 50 86 Q45 55 14 50 Q45 45 50 14 Z M76 14 Q78 22 86 24 Q78 26 76 34 Q74 26 66 24 Q74 22 76 14 Z"
            />
        </svg>
    );
}
